#include "include/instruments.hpp"
#include <iostream>

int main() {
    using namespace inst;

    // Test basic functionality
    Market market{100.0, 0.05, 0.2};  // spot, rate, vol

    // Create some instruments
    auto european = std::make_unique<EuropeanOption>(100.0, 1.0, true);
    auto digital = std::make_unique<DigitalOption>(100.0, 1.0, 10.0);
    auto barrier = std::make_unique<BarrierOption>(100.0, 90.0, 1.0);
    auto zcb = std::make_unique<ZeroCouponBond>(2.0, 1000.0);

    // Test PricingVisitor
    PricingVisitor pricing_visitor(market);
    european->accept(pricing_visitor);
    std::cout << "European option price: " << pricing_visitor.result() << std::endl;

    pricing_visitor = PricingVisitor(market);
    digital->accept(pricing_visitor);
    std::cout << "Digital option price: " << pricing_visitor.result() << std::endl;

    pricing_visitor = PricingVisitor(market);
    barrier->accept(pricing_visitor);
    std::cout << "Barrier option price: " << pricing_visitor.result() << std::endl;

    pricing_visitor = PricingVisitor(market);
    zcb->accept(pricing_visitor);
    std::cout << "ZCB price: " << pricing_visitor.result() << std::endl;

    // Test JsonVisitor
    JsonVisitor json_visitor;
    european->accept(json_visitor);
    std::cout << "European JSON: " << json_visitor.result() << std::endl;

    json_visitor = JsonVisitor();
    digital->accept(json_visitor);
    std::cout << "Digital JSON: " << json_visitor.result() << std::endl;

    json_visitor = JsonVisitor();
    barrier->accept(json_visitor);
    std::cout << "Barrier JSON: " << json_visitor.result() << std::endl;

    json_visitor = JsonVisitor();
    zcb->accept(json_visitor);
    std::cout << "ZCB JSON: " << json_visitor.result() << std::endl;

    // Test Portfolio
    auto portfolio = std::make_unique<Portfolio>();
    portfolio->add(std::move(european), 2.0);
    portfolio->add(std::move(digital), 1.0);

    pricing_visitor = PricingVisitor(market);
    portfolio->accept(pricing_visitor);
    std::cout << "Portfolio price: " << pricing_visitor.result() << std::endl;

    json_visitor = JsonVisitor();
    portfolio->accept(json_visitor);
    std::cout << "Portfolio JSON: " << json_visitor.result() << std::endl;

    return 0;
}

