#include "include/instruments.hpp"
#include <iostream>

int main() {
    using namespace inst;

    // Test complex nested portfolio
    Market market{100.0, 0.05, 0.2};

    // Create some instruments
    auto european1 = std::make_unique<EuropeanOption>(100.0, 1.0, true);
    auto european2 = std::make_unique<EuropeanOption>(110.0, 1.0, false);
    auto digital = std::make_unique<DigitalOption>(100.0, 1.0, 10.0);

    // Create a sub-portfolio
    auto sub_portfolio = std::make_unique<Portfolio>();
    sub_portfolio->add(std::move(european1), 2.0);
    sub_portfolio->add(std::move(digital), 1.0);

    // Create main portfolio
    auto main_portfolio = std::make_unique<Portfolio>();
    main_portfolio->add(std::move(sub_portfolio), 1.0);  // Add sub-portfolio with quantity 1
    main_portfolio->add(std::move(european2), 3.0);     // Add european option with quantity 3

    // Test PricingVisitor on nested portfolio
    PricingVisitor pricing_visitor(market);
    main_portfolio->accept(pricing_visitor);
    std::cout << "Nested portfolio price: " << pricing_visitor.result() << std::endl;

    // Test JsonVisitor on nested portfolio
    JsonVisitor json_visitor;
    main_portfolio->accept(json_visitor);
    std::cout << "Nested portfolio JSON: " << json_visitor.result() << std::endl;

    return 0;
}
